const arrow = '<span aria-hidden="true">↗</span>';
const isCatalogue = location.pathname.endsWith('catalogue.html');
const home = isCatalogue ? 'index.html' : '';
document.querySelector('#site-header').innerHTML = `
  <div class="utility-bar"><div class="container"><span>We are committed to you.</span><div><a href="mailto:sales@instant-international.com">sales@instant-international.com</a><span class="utility-divider"></span><a href="tel:+919222105421">+91 92221 05421</a></div></div></div>
  <header class="main-header"><div class="container nav-wrap"><a class="brand" href="index.html" aria-label="Instant International home"><span class="brand-symbol" aria-hidden="true"></span><span class="brand-name"><b>INSTANT</b><strong>INTERNATIONAL</strong></span></a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="main-nav"><span></span><span></span></button><nav id="main-nav" class="main-nav" aria-label="Main navigation"><a href="index.html" ${!isCatalogue ? 'aria-current="page"' : ''}>Home</a><a href="${home}#about">About us</a><a href="catalogue.html" ${isCatalogue ? 'aria-current="page"' : ''}>Our products</a><a href="${home}#industries">Industries</a><a class="nav-contact" href="${home}#contact">Get in touch ${arrow}</a></nav></div></header>`;
document.querySelector('#site-footer').innerHTML = `<footer class="footer"><div class="container"><div class="footer-main"><div><a class="brand footer-brand" href="index.html" aria-label="Instant International home"><span class="brand-symbol" aria-hidden="true"></span><span class="brand-name"><b>INSTANT</b><strong>INTERNATIONAL</strong></span></a><p>We are committed to you.</p></div><div class="footer-nav"><a href="${home}#about">About us</a><a href="catalogue.html">Our products</a><a href="${home}#industries">Industries</a><a href="${home}#contact">Contact</a></div><a class="footer-download" href="assets/Instant-International-Chemical-Catalogue.xlsx" download>Our product catalogue <span aria-hidden="true">↓</span><small>DOWNLOAD XLSX</small></a></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Instant International. All rights reserved.</span><span>Good chemistry. Lasting conversations.</span><a href="#main" aria-label="Back to top">Back to top ↑</a></div></div></footer>`;
const menu = document.querySelector('.menu-toggle');
menu.addEventListener('click', () => { const open = menu.getAttribute('aria-expanded') !== 'true'; menu.setAttribute('aria-expanded', String(open)); menu.setAttribute('aria-label', open ? 'Close navigation' : 'Open navigation'); document.querySelector('.main-nav').classList.toggle('is-open', open); });
document.querySelectorAll('.main-nav a').forEach(a => a.addEventListener('click', () => { menu.setAttribute('aria-expanded', 'false'); menu.setAttribute('aria-label', 'Open navigation'); document.querySelector('.main-nav').classList.remove('is-open'); }));
document.addEventListener('keydown', e => { if (e.key === 'Escape') { menu.setAttribute('aria-expanded', 'false'); menu.setAttribute('aria-label', 'Open navigation'); document.querySelector('.main-nav').classList.remove('is-open'); } });
